const CACHE='foco-shell-v3';const BASE=new URL('./',self.location.href);const ASSETS=['','style.css','app.js','model.mjs','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png'].map(x=>new URL(x,BASE).href);self.addEventListener('install',e=>{e.waitUntil((async()=>{const c=await caches.open(CACHE);for(const u of ASSETS){try{const r=await fetch(u);if(r.ok&&!r.redirected)await c.put(u,r)}catch{}}await self.skipWaiting()})())});self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith('foco-shell-')&&k!==CACHE)await caches.delete(k);await self.clients.claim()})()));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||!ASSETS.includes(e.request.url))return;e.respondWith((async()=>{try{let r=await fetch(e.request);if(r.ok&&!r.redirected){let c=await caches.open(CACHE);await c.put(e.request.url,r.clone())}return r}catch{return await caches.match(e.request.url)||new Response('Conecte-se à internet para abrir o aplicativo pela primeira vez.',{status:503})}})())});self.addEventListener('push',e=>{let d={title:'Foco Até o Final',body:'Sua agenda está esperando por você.'};try{d={...d,...e.data.json()}}catch{}e.waitUntil(self.registration.showNotification(d.title,{body:d.body,icon:new URL('icon-192.png',BASE).href,badge:new URL('icon-192.png',BASE).href,tag:d.tag||'foco',data:{url:new URL('./#agenda',BASE).href}}))});self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil((async()=>{const target=e.notification.data?.url||new URL('./#agenda',BASE).href;const list=await clients.matchAll({type:'window',includeUncontrolled:true});for(const c of list){if(new URL(c.url).origin===new URL(target).origin){await c.navigate(target);return c.focus()}}return clients.openWindow(target)})())});